from pathlib import Path
import pandas as pd
import json
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import letter
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import inch
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, Image, Preformatted

ROOT = Path(__file__).parent; OUT = ROOT / "output" / "pdf"; OUT.mkdir(parents=True, exist_ok=True)
pdf = OUT / "MovieGraph_NoSQL_Homework_Report.pdf"
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name="TitleCenter", parent=styles["Title"], alignment=TA_CENTER, textColor=colors.HexColor("#17365D"), fontSize=22, leading=27, spaceAfter=14))
styles.add(ParagraphStyle(name="Sub", parent=styles["Normal"], alignment=TA_CENTER, textColor=colors.HexColor("#4F6B8A"), fontSize=11, leading=15, spaceAfter=18))
styles.add(ParagraphStyle(name="H", parent=styles["Heading2"], textColor=colors.HexColor("#17365D"), spaceBefore=9, spaceAfter=6))
styles.add(ParagraphStyle(name="Small", parent=styles["Normal"], fontSize=8.1, leading=10))
styles.add(ParagraphStyle(name="CodeSmall", fontName="Courier", fontSize=7.2, leading=9, leftIndent=8, backColor=colors.HexColor("#F3F6F9")))
def P(x, style="BodyText"): return Paragraph(x, styles[style])
def footer(c, d):
    c.saveState(); c.setFont("Helvetica", 8); c.setFillColor(colors.HexColor("#667085")); c.drawString(.65*inch,.4*inch,"MovieGraph | NoSQL databases homework"); c.drawRightString(7.85*inch,.4*inch,f"Page {d.page}"); c.restoreState()

story = [P("MovieGraph", "TitleCenter"), P("Movie recommendation analytics with MongoDB and Neo4j", "Sub")]
story += [P("Abstract", "H"), P("This project uses the downloaded MovieLens ml-latest-small dataset to build a movie analytics and recommendation system with two NoSQL databases. MongoDB stores movie, rating, and tag documents and answers aggregation questions such as which movies are highly rated with enough evidence and which genres receive the most rating activity. Neo4j models users, movies, and genres as a graph and answers relationship-oriented questions such as which movies can be recommended through users with overlapping high ratings. The two databases solve complementary parts of the same problem."), P("Motivation and goal", "H"), P("Movie recommendation is a meaningful use case because a useful recommendation depends on both numerical evidence and relationships. A document database is convenient for flexible records and analytical summaries. A graph database is convenient for traversing user-to-movie-to-user paths. The project goal is to compare these approaches using the same publicly available dataset and produce reproducible insights rather than a generic database demonstration."), P("Dataset", "H"), P("The experiment uses MovieLens ml-latest-small, downloaded from GroupLens. It contains 100,836 ratings, 3,683 tag applications, 9,742 movies, and 610 users. The files are movies.csv, ratings.csv, tags.csv, and links.csv. The dataset ZIP is not included with the submission; the report provides the official download link and the code expects the extracted folder ml-latest-small/.")]
story += [P("Workflow", "H"), P("1. Download and extract the MovieLens ZIP. 2. Use Python, pandas, and matplotlib for a local validation analysis. 3. Load movies, ratings, and tags into MongoDB collections and run aggregation pipelines. 4. Load users, movies, ratings, and derived genre relationships into Neo4j. 5. Run graph recommendation queries and compare the modeling experience with MongoDB and an RDBMS baseline.")]
story += [PageBreak(), P("Data model and implementation", "H")]
model = [[P("Entity", "Small"), P("MongoDB", "Small"), P("Neo4j", "Small")], [P("Movie", "Small"), P("movies document with title and genres", "Small"), P(":Movie node with unique movieId", "Small")], [P("Rating", "Small"), P("ratings document with userId, movieId, rating, timestamp", "Small"), P(":User-[:RATED {rating}]->:Movie", "Small")], [P("Genre", "Small"), P("Pipe-delimited genre field split during analytics", "Small"), P(":Movie-[:IN_GENRE]->:Genre", "Small")], [P("Tag", "Small"), P("tags document with free-text tag", "Small"), P("Can be added as :Tag nodes for tag traversal", "Small")]]
t = Table(model, colWidths=[1.0*inch, 2.95*inch, 2.7*inch]); t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#17365D")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("GRID",(0,0),(-1,-1),.35,colors.HexColor("#B8C4D0")),("VALIGN",(0,0),(-1,-1),"TOP"),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F3F6F9")])]))
story += [t, P("MongoDB implementation", "H"), P("MongoDB uses three collections. The ratings collection remains event-like and is indexed by movieId and userId. The primary pipeline groups ratings by movie, filters out movies with fewer than 50 ratings, sorts by average rating and rating count, and joins titles with $lookup. A second pipeline splits genres and calculates rating activity by genre. This demonstrates flexible documents, indexing, grouping, filtering, and joining without requiring a fixed relational schema."), P("Neo4j implementation", "H"), P("Neo4j uses User, Movie, and Genre nodes. RATED relationships retain rating and timestamp properties. IN_GENRE relationships are derived by splitting the source genre field. The recommendation query finds another user who rated one of the target user's liked movies highly, then collects candidate movies that the other user also rated highly. Candidate movies already rated by the target user are excluded."), P("Representative queries", "H"), Preformatted("db.ratings.aggregate([\n  {$group: {_id: '$movieId', ratingCount: {$sum: 1},\n    averageRating: {$avg: '$rating'}}},\n  {$match: {ratingCount: {$gte: 50}}},\n  {$sort: {averageRating: -1}}\n])", styles["CodeSmall"]), Spacer(1, 5), Preformatted("MATCH (u:User {userId:1})-[r1:RATED]->(liked)<-[:RATED]-(other)\n      -[r3:RATED]->(candidate)\nWHERE r1.rating >= 4 AND r3.rating >= 4\nRETURN candidate.title, count(other) AS sharedUsers\nORDER BY sharedUsers DESC LIMIT 10", styles["CodeSmall"])]

story += [PageBreak(), P("Results and analytics", "H")]
data = ROOT / "ml-latest-small"; movies = pd.read_csv(data/"movies.csv"); ratings = pd.read_csv(data/"ratings.csv"); tags = pd.read_csv(data/"tags.csv")
stats = ratings.groupby("movieId").agg(rating_count=("rating","count"), average_rating=("rating","mean")).reset_index().merge(movies,on="movieId")
qualified = stats[stats.rating_count >= 50].sort_values(["average_rating","rating_count"], ascending=False)
rows = [[P("Movie", "Small"),P("Avg rating","Small"),P("Ratings","Small")]] + [[P(str(r.title)[:52],"Small"),P(f"{r.average_rating:.2f}","Small"),P(str(int(r.rating_count)),"Small")] for r in qualified.head(10).itertuples()]
t2 = Table(rows, colWidths=[4.25*inch,1.05*inch,1.0*inch]); t2.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#17365D")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("GRID",(0,0),(-1,-1),.3,colors.HexColor("#B8C4D0")),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F3F6F9")]),("VALIGN",(0,0),(-1,-1),"TOP")]))
genre = stats.assign(genre=stats.genres.str.split("\\|", regex=True)).explode("genre").groupby("genre").agg(movies=("movieId","nunique"), average_rating=("average_rating","mean")).reset_index().sort_values("movies", ascending=False)
story += [P("MongoDB-style results", "H"), P("The query uses a minimum-evidence threshold of 50 ratings so that a single rating cannot dominate the ranking. The exact table below is generated from the downloaded dataset by the included Python script."), t2, Spacer(1, 8), Image(str(ROOT/"outputs/movie_analytics.png"), width=5.9*inch, height=3.2*inch), P("The visualization shows the most common movie genres. The project also exports genre_summary.csv and top_tags.csv for additional analysis."), P("Neo4j recommendation insight", "H"), P("The graph query is designed to recommend unrated movies to user 1 using collaborative evidence: users who gave high ratings to a movie liked by user 1 are used as neighborhood evidence, and their other highly rated movies become candidates. The graph representation makes this multi-hop pattern explicit and easy to extend with genre similarity, tag relationships, or weighted shortest paths.")]

story += [PageBreak(), P("Recommendation comparison and actual query times", "H"), P("Both databases are benchmarked with the same neighborhood method: for user 1, use movies rated at least 4.0 as taste signals; find other users who rated those movies at least 4.0; then rank candidate movies the target user has not rated by the number of supporting users and their mean rating. The benchmark consumes all returned rows, performs one warm-up and five timed runs by default, and reports client-observed wall-clock time in milliseconds.")]
benchmark_path = ROOT / "outputs" / "recommendation_benchmark.json"
if benchmark_path.exists():
    benchmark = json.loads(benchmark_path.read_text())
    bench_table = [[P("Database", "Small"), P("Median ms", "Small"), P("Minimum ms", "Small"), P("Run samples (ms)", "Small")],
        [P("MongoDB", "Small"), P(str(benchmark["mongo"]["median_ms"]), "Small"), P(str(benchmark["mongo"]["min_ms"]), "Small"), P(", ".join(map(str, benchmark["mongo"]["samples_ms"])), "Small")],
        [P("Neo4j", "Small"), P(str(benchmark["neo4j"]["median_ms"]), "Small"), P(str(benchmark["neo4j"]["min_ms"]), "Small"), P(", ".join(map(str, benchmark["neo4j"]["samples_ms"])), "Small")]]
    bt = Table(bench_table, colWidths=[1.05*inch, 1.05*inch, 1.05*inch, 3.25*inch]); bt.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#17365D")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("GRID",(0,0),(-1,-1),.3,colors.HexColor("#B8C4D0")),("VALIGN",(0,0),(-1,-1),"TOP"),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F3F6F9")])]))
    same_text = "The ordered top-10 movie IDs match across both databases." if benchmark["same_ordered_recommendations"] else "The ordered top-10 results differ; the output tables below show the differences."
    rec_rows = [[P("Rank", "Small"), P("MongoDB result", "Small"), P("Neo4j result", "Small")]]
    for i in range(max(len(benchmark["mongo"]["results"]), len(benchmark["neo4j"]["results"]))):
        mr = benchmark["mongo"]["results"][i] if i < len(benchmark["mongo"]["results"]) else {}
        nr = benchmark["neo4j"]["results"][i] if i < len(benchmark["neo4j"]["results"]) else {}
        def rec_text(row):
            return f"{row.get('recommendation','')} (support {row.get('sharedUsers','')}, mean {row.get('predictedRating','')})" if row else ""
        rec_rows.append([P(str(i+1), "Small"), P(rec_text(mr), "Small"), P(rec_text(nr), "Small")])
    rt = Table(rec_rows, colWidths=[.45*inch, 3.0*inch, 3.0*inch]); rt.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#17365D")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("GRID",(0,0),(-1,-1),.25,colors.HexColor("#B8C4D0")),("VALIGN",(0,0),(-1,-1),"TOP"),("FONTSIZE",(0,0),(-1,-1),7.5),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F3F6F9")])]))
    story += [bt, Spacer(1, 5), P(same_text), rt]
else:
    story += [P("Actual timings and recommendation comparison are generated by benchmark_recommendations.py after both databases are running. The report builder inserts the measured local results when outputs/recommendation_benchmark.json exists. No execution times are assumed.", "Small")]

story += [PageBreak(), P("Rubric evidence, comparison, and best practices", "H")]
rubric = [[P("Criterion","Small"),P("Evidence","Small")],[P("Meaningful goal","Small"),P("Movie analytics plus explainable collaborative recommendations.","Small")],[P("Workflow","Small"),P("Downloaded CSVs -> Python validation -> MongoDB aggregations -> Neo4j graph loading -> comparison.","Small")],[P("Innovation","Small"),P("The same recommendation problem is intentionally split between document analytics and graph traversal.","Small")],[P("Technical difficulty","Small"),P("Two Python database drivers, indexes/constraints, genre derivation, multi-hop recommendation query, and visualization.","Small")],[P("Analytics","Small"),P("Rating thresholds, averages, counts, genre summaries, tag summaries, and graph-based candidate ranking.","Small")],[P("Scale-out","Small"),P("Docker Compose provides reproducible services; MongoDB sharding is discussed as a free-tier extension.","Small")],[P("Programming","Small"),P("Python, pandas, PyMongo, Neo4j driver, JavaScript pipelines, Cypher, and matplotlib.","Small")],[P("Visualization","Small"),P("Generated genre bar chart and CSV outputs ready for MongoDB Charts.","Small")],[P("LLM use","Small"),P("LLM assistance was used for schema/query drafts; code was executed and numerical results were generated locally.","Small")]]
t3 = Table(rubric, colWidths=[1.35*inch,5.55*inch]); t3.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#17365D")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("GRID",(0,0),(-1,-1),.3,colors.HexColor("#B8C4D0")),("VALIGN",(0,0),(-1,-1),"TOP"),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F3F6F9")])]))
story += [t3, P("MongoDB, Neo4j, and RDBMS comparison", "H"), P("MongoDB was easiest for loading source CSV rows as flexible documents and calculating rating summaries with aggregation stages. Neo4j required more deliberate identity constraints and relationship design, but the recommendation query was more natural because the relevant evidence is a path through users and movies. An RDBMS would provide strict integrity and familiar joins, but the graph query would require several join tables and would be less expressive for exploratory traversal. MongoDB is the best fit for document-oriented analytics; Neo4j is the best fit for relationship-oriented recommendations."), P("Scale-out and best practices", "H"), P("The Docker Compose file makes the two database services reproducible. A larger experiment could shard MongoDB ratings by a well-distributed key such as hashed movieId or userId after benchmarking the workload. Important practices were to index both sides of common lookups, create Neo4j uniqueness constraints before MERGE loads, preserve source identifiers, use a rating-count threshold to avoid unstable rankings, and avoid claiming that a small development dataset represents all movie viewers."), P("Technical difficulties and limitations", "H"), P("The MovieLens data stores genres as a pipe-delimited string, so both systems require a transformation: MongoDB splits it during aggregation and Neo4j creates Genre relationships. The current recommendation query is not a production recommender: it does not evaluate precision or recall, does not include time decay, and uses a simple neighborhood heuristic. A future version could add train/test evaluation, weighted similarity, tag relationships, and a larger MovieLens benchmark dataset."), P("LLM disclosure", "H"), P("An LLM was used to propose the project framing, schema alternatives, query drafts, and report organization. The dataset was downloaded separately, the scripts were executed locally, and the reported values were generated from the local CSV files. If required, a screenshot of the prompt history can be attached as evidence.")]

story += [PageBreak(), P("Conclusion and sources", "H"), P("MovieGraph demonstrates that MongoDB and Neo4j can solve complementary parts of one real data problem. MongoDB provides flexible storage and aggregations for rating and tag activity. Neo4j provides an intuitive representation for collaborative recommendation paths. The project is reproducible from the official MovieLens download link, and the dataset itself is deliberately excluded from the submission package."), P("Sources", "H"), P("MovieLens download: https://files.grouplens.org/datasets/movielens/ml-latest-small.zip<br/>MovieLens datasets: https://grouplens.org/datasets/movielens/<br/>MovieLens paper: https://doi.org/10.1145/2827872<br/>MongoDB aggregation: https://www.mongodb.com/docs/manual/core/aggregation-pipeline/<br/>Neo4j Cypher: https://neo4j.com/docs/cypher-manual/current/<br/>Neo4j Python driver: https://neo4j.com/docs/python-manual/current/")]
SimpleDocTemplate(str(pdf), pagesize=letter, rightMargin=.65*inch, leftMargin=.65*inch, topMargin=.6*inch, bottomMargin=.65*inch, title="MovieGraph NoSQL Homework Report").build(story, onFirstPage=footer, onLaterPages=footer)
print(pdf)
